def esc(t):
    t=t.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
    t=t.replace("\\'","'").replace("'","\\'").replace('"','\\"')
    return t
for i,folder in enumerate(['values','values-es','values-ca']):
    out=['<?xml version="1.0" encoding="utf-8"?>','<resources>']
    for k,v in S.items(): out.append(f'    <string name="{k}">{esc(v[i])}</string>')
    for k,v in P.items():
        out.append(f'    <plurals name="{k}">')
        out.append(f'        <item quantity="one">{esc(v[i][0])}</item>')
        out.append(f'        <item quantity="other">{esc(v[i][1])}</item>')
        out.append('    </plurals>')
    out.append('</resources>')
    os.makedirs(f'{R}/{folder}',exist_ok=True)
    open(f'{R}/{folder}/strings.xml','w').write('\n'.join(out)+'\n')
print(len(S),len(P))

